pub async fn parallel_vector_search(query: &[f32], corpus: &[Vec<f32>], top_k: usize) -> Vec<(usize, f32)> {
    use rayon::prelude::*;
    let mut scored: Vec<(usize, f32)> = corpus
        .par_iter()
        .enumerate()
        .map(|(id, vec)| (id, dot_product(query, vec)))
        .collect();
    scored.par_sort_unstable_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
    scored.truncate(top_k);
    scored
}


